// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address _originalOwner) public {
        vm.assume(_originalOwner != address(0));
        // Ensure original owner is set via constructor (msg.sender is this contract in setUp)
        // We can't change owner before, so we just use the deployed owner
        address ownerBefore = c.owner();
        c.setOwner(_owner);
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore);
    }
}

