// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Restrict to valid admin caller (the deployer is admin)
        vm.assume(_owner != address(0));
        // Call setOwner and capture the return value
        bool success = c.setOwner(_owner);
        // The reference always returns true, the mutant returns false
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        if (newOwner == address(0)) return;
        c.setOwner(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}
